#!/usr/bin/env python3
"""Self-contained OFFLINE Linux archival gate. No services, journal, or network.

Run as an ordinary user first; --ownership is a separate explicit root-only test
using existing hids-journal/hids-ingest NSS identities and disposable trees only.
Embedded artifacts are extracted only into a newly created private directory.
"""
import argparse
import base64
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import pwd
import sys
import tempfile
import unittest

PAYLOAD = {'docs/validation/m2-runtime-acceptance/resources.py': {'sha256': 'f7a241c6bdfe47ca50a556c01a642b47dd32129d2071ae8bf848d322983022bb', 'base64': ''}, 'docs/validation/m2-runtime-acceptance/probe.py': {'sha256': '2c7a22c6ea0c7d2143536c5af90c60b6bda3965f43f1a877181f2a54ad9a4a5e', 'base64': ''}, 'tests/unit/test_m2_runtime_archival.py': {'sha256': '6ac325c4b184d5c1dd9b7cd21e5eda42006b00b8f1c5e2b07b00c5d43a09d507', 'base64': ''}}

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--ownership', action='store_true')
    args = parser.parse_args()
    if not sys.platform.startswith('linux'):
        parser.error('Linux required; host mocks do not satisfy this gate')
    if args.ownership != (os.geteuid() == 0):
        parser.error('ordinary user required, except explicit root --ownership')
    alternate = Path('/dev/shm')
    with tempfile.TemporaryDirectory(prefix='hids-linux-archive-gate-') as temporary:
        root = Path(temporary).resolve()
        if not (alternate.is_dir() and os.access(alternate, os.W_OK) and alternate.stat().st_dev != root.stat().st_dev):
            raise RuntimeError('actual writable cross-device /dev/shm required; no mounts/configuration attempted')
        for name, record in PAYLOAD.items():
            data = base64.b64decode(record['base64'], validate=True)
            if hashlib.sha256(data).hexdigest() != record['sha256']:
                raise RuntimeError('embedded artifact digest mismatch')
            path = root/name
            path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
            with path.open('xb') as stream:
                stream.write(data)
        unit = root/'tests/unit/test_m2_runtime_archival.py'
        spec = importlib.util.spec_from_file_location('archival_gate_tests', unit)
        tests = importlib.util.module_from_spec(spec); spec.loader.exec_module(tests)
        if args.ownership:
            reader, ingest = pwd.getpwnam('hids-journal'), pwd.getpwnam('hids-ingest')
            if not (reader.pw_uid == 997 and ingest.pw_uid != 0 and ingest.pw_uid != reader.pw_uid):
                raise RuntimeError('existing dedicated account policy mismatch')
            class CrossAccount(tests.ArchiveTests):
                def test_real_cross_account_preservation(self):
                    r = tests.resources
                    for directory, owner in ((self.runtime/'code', reader), (self.database, ingest)):
                        os.chown(directory, owner.pw_uid, owner.pw_gid)
                    os.chown(self.runtime/'code/data', reader.pw_uid, reader.pw_gid)
                    second = self.runtime/'ingest-owned'; second.write_bytes(b'synthetic ingestion evidence')
                    second.chmod(0o600); os.chown(second, ingest.pw_uid, ingest.pw_gid)
                    for name in ('journal.sqlite', 'journal.sqlite-wal', 'journal.sqlite-shm'):
                        os.chown(self.database/name, ingest.pw_uid, ingest.pw_gid)
                    self.manifest = r.tree_manifest(self.runtime)
                    self.inv = tests.FakeInventory(self.runtime, self.database, self.evidence)
                    self.ingest = ingest
                    with tempfile.TemporaryDirectory(prefix='hids-linux-cross-owner-', dir='/dev/shm') as destination:
                        evidence = Path(destination)
                        inv = tests.FakeInventory(self.runtime, self.database, evidence)
                        receipts = r.prepare_archives(inv, self.database, ingest)
                        for receipt in receipts: r.verify_archive(receipt)
                        self.assertEqual((evidence/'runtime/code/data').stat().st_uid, reader.pw_uid)
                        self.assertEqual((evidence/'runtime/code').stat().st_gid, reader.pw_gid)
                        self.assertEqual((evidence/'runtime/ingest-owned').stat().st_uid, ingest.pw_uid)
                        self.assertEqual((evidence/'database/journal.sqlite').stat().st_uid, ingest.pw_uid)
                        self.assertEqual((evidence/'database').stat().st_gid, ingest.pw_gid)
                        self.assert_original()
            suite = unittest.TestSuite([CrossAccount('test_real_cross_account_preservation')])
        else:
            suite = unittest.defaultTestLoader.loadTestsFromModule(tests)
        result = unittest.TextTestRunner(verbosity=2).run(suite)
        summary = dict(platform=sys.platform, ownership=args.ownership, tests=result.testsRun,
                       failures=len(result.failures), errors=len(result.errors), skipped=len(result.skipped),
                       embedded_sha256={name: record['sha256'] for name, record in PAYLOAD.items()})
        print(json.dumps(summary, sort_keys=True))
        return 0 if result.wasSuccessful() and not result.skipped else 1

if __name__ == '__main__':
    raise SystemExit(main())
